{"requirement_id": "I2-019", "candidate_version": 1, "candidate_sha256": "659dd8ca5337dff71e3655223b8a0d1a241d8cb63a9a90954ab4f395f0339545", "previous_candidate": "@prefix sh:   <http://www.w3.org/ns/shacl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix nltl: <https://w3id.org/nltl/vocab#> .
